//api.js
import axios from "axios";

const API = axios.create({
  baseURL: process.env.REACT_APP_AUTH_API,
});

const restaurantAPI = axios.create({
  baseURL: process.env.REACT_APP_RESTAURANT_API,
});

// Add an interceptor to restaurantAPI to include the token
restaurantAPI.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`; // Or however your backend expects the token
    }
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

export { API, restaurantAPI };
